struct lcperf_test_data *
lcperf_test_vector_get_dummy(const struct lcperf_options *options)
{
	struct lcperf_test_data *test_data = NULL;
	uint32_t plain_len;

	test_data = rte_malloc(NULL, sizeof(struct lcperf_test_data), 0);
	if (test_data == NULL)
		return NULL;

	if (options->op_type == LCPERF_OP_SYM) {
		if (options->sym_op == LCPERF_CRYPTO_SYM_OP_CIPHER_ONLY) {
			switch (options->cipher_algo) {
			case DAO_LC_FC_ENC_CIPHER_AES_CBC:
				if (options->cipher_key_sz == 16) {
					memcpy(&test_data->sym_params, &aes_cbc_128_test_data,
					       sizeof(struct lcperf_test_sym_params));
				} else if (options->cipher_key_sz == 24) {
					memcpy(&test_data->sym_params, &aes_cbc_192_test_data,
					       sizeof(struct lcperf_test_sym_params));
				} else if (options->cipher_key_sz == 32) {
					memcpy(&test_data->sym_params, &aes_cbc_256_test_data,
					       sizeof(struct lcperf_test_sym_params));
				} else {
					RTE_LOG(ERR, USER1,
						"Unsupported key length for AES CBC: %u\n",
						options->cipher_key_sz);
					goto free_test_data;
				}
				break;
			default:
				RTE_LOG(ERR, USER1, "Unsupported cipher algorithm: %u\n",
					options->cipher_algo);
				goto free_test_data;
			}

			memcpy(test_data->plaintext.data, test_data->sym_params.plaintext.data,
			       test_data->sym_params.plaintext.len);
			test_data->plaintext.len = test_data->sym_params.plaintext.len;
			memcpy(test_data->ciphertext.data, test_data->sym_params.ciphertext.data,
			       test_data->sym_params.ciphertext.len);
			test_data->ciphertext.len = test_data->sym_params.ciphertext.len;
		} else if (options->sym_op == LCPERF_CRYPTO_SYM_OP_AUTH_ONLY) {
			switch (options->auth_algo) {
			case DAO_LC_HASH_TYPE_SHA1:
				if (options->auth_key_sz == 0) {
					memcpy(&test_data->sym_params, &sha1_test_data,
					       sizeof(sha1_test_data));
				} else if (options->auth_key_sz == 20) {
					memcpy(&test_data->sym_params, &sha1_hmac_test_vector,
					       sizeof(sha1_hmac_test_vector));
				} else if (options->auth_key_sz == 1024) {
					memcpy(&test_data->sym_params,
					       &sha1_hmac_1024B_test_vector,
					       sizeof(sha1_hmac_1024B_test_vector));
				} else {
					RTE_LOG(ERR, USER1,
						"Unsupported auth key size for sha1 auth/hmac: %u (supported: 0, 20, 1024)\n",
						options->auth_key_sz);
					goto free_test_data;
				}
				break;
			default:
				RTE_LOG(ERR, USER1,
					"Supported algorithms and key sizes:\n"
					"sha1 : key sizes 0, 20, 1024\n");
				RTE_LOG(ERR, USER1,
					"Unsupported hash/hmac algorithm: %u\n",
					options->auth_algo);
				goto free_test_data;
			}

			memcpy(test_data->plaintext.data, test_data->sym_params.plaintext.data,
			       test_data->sym_params.plaintext.len);
			test_data->plaintext.len = test_data->sym_params.plaintext.len;
			memcpy(test_data->digest.data, test_data->sym_params.digest.data,
			       test_data->sym_params.digest.len);
			test_data->digest.len = test_data->sym_params.digest.len;
		} else {
			RTE_LOG(ERR, USER1, "Unsupported symmetric operation type: %u\n",
				options->sym_op);
			goto free_test_data;
		}
	} else if (options->op_type == LCPERF_OP_COMPRESS) {
		if (options->test_buffer_size > 0) {
			if (options->test_buffer_size > TEST_LC_COMP_MAX_PLAINTEXT_LEN) {
				RTE_LOG(ERR, USER1,
					"Compression buffer size %u exceeds maximum supported size %u\n",
					options->test_buffer_size, TEST_LC_COMP_MAX_PLAINTEXT_LEN);
				goto free_test_data;
			}
			random_text_generate(test_data->comp_plain_data,
					     (size_t)options->test_buffer_size);
			plain_len = options->test_buffer_size;
		} else {
			plain_len = sizeof(comp_plain_text);
			memcpy(test_data->comp_plain_data, comp_plain_text, plain_len);
		}

		test_data->comp_plain_len = plain_len;
		test_data->comp_out_base =
			rte_zmalloc(NULL, options->burst_size * TEST_LC_COMP_MAX_OUTPUT_LEN, 0);
		if (test_data->comp_out_base == NULL) {
			RTE_LOG(ERR, USER1, "Failed to allocate comp output buffer\n");
			goto free_test_data;
		}
		test_data->comp_compressed_data = NULL;
		test_data->comp_compressed_len = 0;
	} else if (options->op_type == LCPERF_OP_DECOMPRESS) {
		test_data->comp_plain_len = sizeof(comp_plain_text);
		test_data->comp_out_base =
			rte_zmalloc(NULL, options->burst_size * TEST_LC_COMP_MAX_OUTPUT_LEN, 0);
		if (test_data->comp_out_base == NULL) {
			RTE_LOG(ERR, USER1, "Failed to allocate decomp output buffer\n");
			goto free_test_data;
		}
		test_data->comp_compressed_data = rte_malloc(NULL, sizeof(comp_compressed_text), 0);
		if (test_data->comp_compressed_data == NULL) {
			RTE_LOG(ERR, USER1, "Failed to allocate decomp input buffer\n");
			rte_free(test_data->comp_out_base);
			goto free_test_data;
		}
		memcpy(test_data->comp_compressed_data, comp_compressed_text,
		       sizeof(comp_compressed_text));
		test_data->comp_compressed_len = sizeof(comp_compressed_text);
	}

	return test_data;

free_test_data:
	rte_free(test_data);
	return NULL;
}

void
lcperf_test_vector_free(struct lcperf_test_data *test_data)
{
	if (test_data == NULL)
		return;

	if (test_data->comp_out_base != NULL) {
		rte_free(test_data->comp_out_base);
		test_data->comp_out_base = NULL;
	}
	if (test_data->comp_compressed_data != NULL) {
		rte_free(test_data->comp_compressed_data);
		test_data->comp_compressed_data = NULL;
	}
	rte_free(test_data);
}
